{
  "diagnosis": "Errors arise from three mechanisms: (1) unsupported inference or over-treating rare contraindications instead of selecting the indicated agent; (2) failing to match the specific diagnosis to a drug class with the exact indication; (3) confusing look-alike drugs or choosing routes/targets that are unsafe for the patient's comorbidity.",
  "skills": [
    {
      "id": "diagnosis_drug_class_match",
      "text": "Before selecting, restate the working diagnosis and map it to the drug class that is indicated for that exact diagnosis. Reject any option whose mechanism does not match the disease process even if it is a plausible class for another condition. Do not substitute a broader class for a specifically indicated agent unless the broader option is also explicitly indicated."
    },
    {
      "id": "contraindication_precision",
      "text": "When a historical condition is mentioned (e.g., prior cancer, seizure disorder, myasthenia gravis), determine whether it is a true absolute contraindication, a relative caution, or irrelevant to the proposed mechanism. Do not avoid or reject the indicated option solely because of a remote, resolved, or mechanism-unrelated history. Prefer lower systemic exposure or a safer alternative only when the patient-specific risk is actually increased."
    },
    {
      "id": "acute_vs_chronic_indication",
      "text": "Distinguish acute inflammatory or infectious presentations from chronic functional or hormonal conditions. Match treatment urgency and route to the time course and severity; do not choose chronic-management drugs for acute symptoms or acute rescue drugs for chronic prevention unless the diagnosis specifically requires it."
    },
    {
      "id": "drug_similarity_check",
      "text": "When options include sound-alike, look-alike, brand/generic pairs, or overlapping names, verify each by its actual class and indication rather than by name familiarity. Do not assume two options are equivalent; compare mechanism, route, and patient-specific safety before selecting."
    },
    {
      "id": "symptom_severity_palliation",
      "text": "For symptom-driven presentations (pain, discomfort, dryness, nausea, bronchospasm), first identify whether the priority is symptomatic relief or disease modification, then choose the agent whose primary action targets that priority. Avoid agents that treat a secondary or unlikely cause unless evidence supports that cause."
    },
    {
      "id": "comorbidity_interaction_screen",
      "text": "After selecting a candidate, screen it against the patient's stated comorbidities and current medicines for clinically meaningful interactions or disease-specific worsening (e.g., bronchospasm risk, seizure threshold, neuromuscular transmission, bleeding, GI irritation). If the candidate is acceptable, proceed; if not, choose the best alternative among the remaining options rather than defaulting to a non-indicated drug."
    }
  ],
  "focus_terms": [
    "indicated for the diagnosis",
    "absolute contraindication",
    "relative caution",
    "mechanism of action",
    "acute versus chronic",
    "brand-generic pair",
    "patient-specific safety"
  ],
  "modules": {
    "patient_evidence": "Identify the stated condition, symptom duration and severity, current medicines, and all relevant past medical history. Mark each historical fact as active, resolved, or unknown; do not treat a missing fact as present or a resolved condition as currently active.",
    "safety_check": "For each candidate option, check mechanism-specific contraindications and interactions against the patient's active conditions and current medicines. Classify each risk as absolute contraindication, relative caution, or not clinically relevant rather than using a blanket avoidance rule.",
    "option_selection": "Choose the option whose drug class matches the working diagnosis and whose route and mechanism fit the acuity and patient-specific safety profile. Prefer the most specifically indicated agent; reject unrelated, look-alike, or disease-worsening options."
  }
}

{
  "diagnosis": "The agent's errors cluster into three mechanisms: (1) it selects an option that is already failing or already in use instead of switching to a mechanistically different agent for the same indication; (2) it ignores the stated diagnosis or mutation-defined indication and picks a drug from an unrelated class; (3) it treats a missing safety fact as if it were present, or lets a comorbidity override the primary indication. The existing modules are directionally correct but lack explicit decision rules for these failure modes.",
  "skills": [
    {
      "id": "indication_first",
      "text": "Before comparing options, restate the working diagnosis and the specific indication it implies. Eliminate any option whose primary approved or guideline-supported use does not match that indication, even if it is otherwise safe. Only then compare the remaining options on patient-specific factors."
    },
    {
      "id": "switch_mechanism_when_current_fails",
      "text": "If the patient is already taking a drug for the target condition and reports inadequate response, intolerance, or that it is no longer working, do not select the same drug or a same-class equivalent as the answer. Prefer an option with a different mechanism of action or a different guideline-endorsed alternative for that condition."
    },
    {
      "id": "mutation_and_subtype_matching",
      "text": "When the diagnosis includes a molecular subtype, receptor status, or gene rearrangement, match the option to that subtype. Do not choose a broadly active agent when a subtype-directed agent is available, and do not choose a subtype-directed agent when the stated subtype does not match its label."
    },
    {
      "id": "missing_fact_is_not_present",
      "text": "Treat any patient fact that is not explicitly stated as unknown, not as absent or normal. Do not exclude an option because of a contraindication, interaction, or comorbidity that was never mentioned. If a safety determination depends on an unstated fact, note the uncertainty rather than assuming the fact."
    },
    {
      "id": "comorbidity_does_not_override_indication",
      "text": "A comorbid condition or concurrent medication is a safety modifier, not a new indication. Use it only to rule out options that are contraindicated or interacting; never let it redirect selection to a drug that does not treat the primary diagnosis."
    },
    {
      "id": "symptomatic_vs_disease_modifying",
      "text": "Distinguish symptomatic or supportive options from disease-modifying or definitive therapy. When the diagnosis calls for definitive treatment, prefer the disease-modifying option over one that only relieves symptoms, unless the question explicitly asks for symptomatic management."
    }
  ],
  "focus_terms": [
    "working diagnosis",
    "indication match",
    "inadequate response",
    "different mechanism",
    "molecular subtype",
    "unknown fact",
    "contraindication",
    "disease-modifying"
  ],
  "modules": {
    "patient_evidence": "Identify the stated condition, its subtype or molecular features if given, current medicines with their response status, and relevant patient facts. Explicitly separate stated facts from unstated ones; do not infer a missing fact as present or absent.",
    "safety_check": "Check patient-specific contraindications and drug interactions using only stated facts. If a safety-relevant fact is missing, record it as unknown and do not use it to exclude an option. Treat comorbidities and concurrent drugs as modifiers, not as new indications.",
    "option_selection": "First filter options by match to the stated diagnosis and subtype. Then remove options that are the same as or equivalent to a currently failing therapy. Then apply safety modifiers from stated facts. Finally, prefer disease-modifying over purely symptomatic options when definitive therapy is indicated."
  }
}

{
  "diagnosis": "The agent fails when the correct choice depends on a patient-specific safety modifier (hepatic impairment, prior liver enzyme elevation, immunosuppression, or interacting current medicine) rather than on the stated indication alone. It also over-trusts the prior answer and does not consistently re-derive the answer from the dialogue. Failures group into: (1) ignoring a stated organ-impairment or metabolic-safety fact when comparing two otherwise indicated options; (2) missing that a current medicine or condition makes one option unsafe or symptom-worsening; (3) selecting an option that does not treat the diagnosed condition when a safer indicated alternative exists; (4) treating a missing fact as present or inventing a contraindication.",
  "skills": [
    {
      "id": "extract_patient_facts",
      "text": "Before comparing options, extract from the dialogue: the stated diagnosis or syndrome, every current medicine, and every relevant patient fact (organ disease, prior abnormal labs, immune status, allergies, pregnancy, age). Use only facts explicitly stated. If a fact is not stated, treat it as unknown and do not assume it is absent or present."
    },
    {
      "id": "indication_filter",
      "text": "First filter options by whether each one treats the stated diagnosis. Eliminate options with no plausible indication for that diagnosis before applying safety tie-breakers. If only one option remains indicated, choose it unless a stated patient fact makes it unsafe."
    },
    {
      "id": "safety_modifier_tiebreak",
      "text": "When two or more options are indicated, compare them on patient-specific safety using stated facts. Prefer the option with less hepatic metabolism or less organ-specific risk when liver disease or prior liver enzyme elevation is stated. Prefer the option that does not worsen the stated problem (for example, avoid adding an immunosuppressant when immune suppression is the concern). Prefer the option with lower interaction risk with the patient's current medicines."
    },
    {
      "id": "interaction_check",
      "text": "For each candidate option, check whether it interacts with any current medicine named in the dialogue. If an interaction is stated or well established, downgrade that option. Do not invent an interaction that is not supported by the dialogue or general drug knowledge."
    },
    {
      "id": "avoid_symptom_worsening",
      "text": "Reject any option whose known effect would aggravate the patient's presenting problem, even if it is otherwise indicated for a related condition. Examples of the mechanism: a sedating medicine when excessive daytime sleepiness is the complaint; a corticosteroid when immune suppression is the concern; a hepatically cleared drug when liver impairment is stated."
    },
    {
      "id": "recompute_answer",
      "text": "Derive the answer from the dialogue and options rather than copying the prior answer. After selecting, verify that the chosen option is both indicated for the stated diagnosis and compatible with every stated patient fact. If the prior answer conflicts with this derivation, follow the derivation."
    }
  ],
  "focus_terms": [
    "liver disease",
    "hepatic metabolism",
    "prior liver enzyme elevation",
    "immunosuppression",
    "current medicine interaction",
    "indicated option",
    "patient-specific safety",
    "symptom worsening"
  ],
  "modules": {
    "patient_evidence": "Extract the stated diagnosis, all current medicines, and all relevant patient facts (organ disease, prior abnormal labs, immune status, allergies). Mark unstated facts as unknown; never treat a missing fact as present or absent.",
    "safety_check": "For each candidate, check contraindications and interactions against stated facts. Downgrade options that are hepatically risky in liver disease, that worsen the presenting problem, or that interact with a current medicine. Do not invent facts or interactions.",
    "option_selection": "Filter by indication first, then break ties by patient-specific safety. Choose the indicated option that best avoids organ-specific risk, symptom worsening, and interactions. Recompute from the dialogue rather than trusting the prior answer."
  }
}

{
  "diagnosis": "Failures cluster into three mechanisms: (1) indication mismatch — selecting a drug that does not treat the stated condition (e.g., choosing a steroid or immunosuppressant when an antiviral or antipsychotic is indicated); (2) safety/contraindication neglect — ignoring that a candidate could worsen the condition or interact with current therapy (e.g., steroids in infection, NSAIDs with GI symptoms or aspirin); (3) within-class discrimination — when multiple options share an indication, failing to pick the one best matched to route, acuity, or patient-specific factors (e.g., intralesional vs systemic steroid, rescue glucagon vs sulfonylurea).",
  "skills": [
    {
      "id": "indication_first",
      "text": "Before comparing options, restate the working diagnosis and the mechanism of action required to treat it. Eliminate any option whose primary indication does not match that mechanism, even if it is otherwise safe."
    },
    {
      "id": "contraindication_and_interaction_scan",
      "text": "For each remaining option, check whether it could worsen the stated condition (e.g., immunosuppression during infection, NSAIDs with GI symptoms, glucose-lowering drugs in hypoglycemia) or interact with the patient's current medicines. Remove options that fail this check; do not assume an unstated fact is present."
    },
    {
      "id": "within_class_tiebreak",
      "text": "When several options share the same indication, choose the one whose route, onset, and patient-specific suitability best fit the scenario (e.g., intralesional over systemic steroid for a localized lesion; rapid rescue agent over a maintenance drug for an acute event)."
    },
    {
      "id": "current_medication_context",
      "text": "Treat the patient's current medicines as active constraints: verify that the selected option is compatible with them and that the current medicine does not already address the target problem, which would make adding a same-class agent redundant or unsafe."
    },
    {
      "id": "missing_fact_guard",
      "text": "If a fact needed to confirm safety or indication is not stated, do not invent it. Either select the option that is safe under the stated facts or flag the uncertainty rather than assuming the missing fact favors an option."
    }
  ],
  "focus_terms": [
    "indication match",
    "contraindication",
    "drug interaction",
    "route of administration",
    "acute vs maintenance",
    "current medication"
  ],
  "modules": {
    "patient_evidence": "Extract the stated diagnosis or syndrome, the current medicines, and any explicit safety-relevant facts (allergies, organ function, pregnancy, infection status). Do not infer unstated facts.",
    "safety_check": "Screen each candidate against the stated condition and current medicines for contraindications, worsening potential, and interactions. Reject options that fail; do not assume absent facts.",
    "option_selection": "Rank surviving options by strength of indication match, then by route/onset and patient-specific suitability. Prefer the option that treats the target mechanism with the fewest safety concerns."
  }
}

{
  "diagnosis": "The agent over-weights a salient comorbidity or current medication and then selects a drug that is either not indicated for the stated diagnosis or is a less appropriate/contraindicated option. Failures cluster into: (1) indication drift — choosing a drug for a comorbidity rather than the active diagnosis; (2) interaction/contraindication neglect — ignoring that the current medicine or patient factor makes an option unsafe or less preferred; (3) first-line vs. alternative confusion — selecting a nonstandard or later-line agent when a standard option is present; (4) missing-fact invention — treating an unstated allergy, renal status, or severity as if present.",
  "skills": [
    {
      "id": "diagnosis_first",
      "text": "Before comparing options, restate the active diagnosis and the immediate treatment goal. Eliminate any option that does not treat that diagnosis or goal, even if it treats a comorbidity or symptom mentioned in the case."
    },
    {
      "id": "current_med_safety",
      "text": "For each remaining option, check it against every stated current medicine and patient-specific factor. If an option is contraindicated, has a clinically significant interaction, or is explicitly less preferred because of a stated factor, deprioritize or eliminate it. Do not assume an unstated allergy, renal function, pregnancy, or severity."
    },
    {
      "id": "first_line_preference",
      "text": "When multiple options are indicated, prefer the standard first-line agent for the active diagnosis unless a stated patient factor makes it unsafe or less effective. Do not choose a later-line, niche, or nonstandard option merely because it is familiar or because a comorbidity is present."
    },
    {
      "id": "indication_over_symptom",
      "text": "Do not let a symptom or comorbidity override the primary diagnosis. Treat the condition that explains the presentation; use symptom relief only when it is the actual treatment goal and no disease-specific therapy is required."
    },
    {
      "id": "missing_fact_guard",
      "text": "If a fact needed to justify an option is not stated, treat it as unknown rather than present. Choose the option whose indication and safety can be supported using only the stated facts."
    },
    {
      "id": "option_elimination",
      "text": "Use a structured elimination pass: first remove options not indicated for the active diagnosis; then remove options contraindicated or disfavored by stated patient factors; then among the remainder choose the most standard, best-supported option."
    }
  ],
  "focus_terms": [
    "active diagnosis",
    "treatment goal",
    "current medicine",
    "contraindication",
    "drug interaction",
    "first-line",
    "less preferred",
    "stated facts",
    "unknown fact",
    "indication"
  ],
  "modules": {
    "patient_evidence": "Identify the stated active diagnosis, the immediate treatment goal, all current medicines, and only the patient facts explicitly given. Mark absent facts as unknown.",
    "safety_check": "Check each candidate against stated current medicines and patient-specific factors. Eliminate or deprioritize options that are contraindicated, interacting, or explicitly less preferred; never invent a missing fact to justify an option.",
    "option_selection": "Select the option that treats the active diagnosis and is safest given stated facts. Prefer the standard first-line agent; do not let a comorbidity or symptom pull selection away from the indicated therapy."
  }
}

{
  "diagnosis": "Failures cluster into three mechanisms: (1) over-weighting a mentioned comorbidity/medication as a contraindication when no explicit interaction is stated, causing avoidance of the correct first-line drug; (2) failing to distinguish 'prior/current use of a drug in the same class' from 'contraindication to retreatment', leading to wrong substitution; (3) selecting an option that treats a secondary symptom rather than the primary diagnosed condition, or ignoring that the correct option is the standard first-line therapy for the stated diagnosis. A fourth mechanism is treating a drug mentioned in the vignette as automatically disqualifying rather than checking whether the option is actually indicated and compatible.",
  "skills": [
    {
      "id": "primary_indication_first",
      "text": "When choosing among options, first identify the single primary diagnosis stated or strongly implied in the case, then select the option whose approved indication matches that diagnosis. Do not let a secondary symptom (e.g., acne, bloating, pain) or a comorbidity drive selection unless the primary diagnosis is itself a symptom-management problem. If two options both plausibly treat the primary diagnosis, prefer the one that is standard first-line for that diagnosis in the described patient context."
    },
    {
      "id": "mentioned_drug_not_auto_contraindication",
      "text": "A medication named in the dialogue is not by itself a contraindication to another option. Only treat a current or prior medication as disqualifying if the case states or strongly implies a specific adverse interaction, allergy, or organ contraindication. If no such fact is given, do not invent one; instead compare options on indication and known safety profile."
    },
    {
      "id": "retreatment_vs_contraindication",
      "text": "Distinguish prior exposure to a drug or drug class from a true contraindication. Prior use of an agent (including biologics) does not automatically rule out retreatment or use of a related agent unless the case states intolerance, resistance, or a specific contraindication. When the primary diagnosis is unchanged and the prior agent is indicated, retreatment or a same-class alternative may be correct."
    },
    {
      "id": "comorbidity_compatibility_check",
      "text": "When the patient has a stated comorbidity or is on a chronic medication, check whether each candidate option is compatible with that context rather than assuming incompatibility. Prefer an option that treats the primary diagnosis and is known to be usable alongside the patient's existing therapy; reject options that are clearly inappropriate for the primary diagnosis or that are known to worsen the comorbidity."
    },
    {
      "id": "avoid_symptom_only_and_unrelated_options",
      "text": "Eliminate options that treat only a secondary symptom, an unrelated condition, or a condition not present in the case. Also eliminate options from unrelated drug classes (e.g., hormones, antineoplastics, laxatives) when the primary diagnosis requires a different class. The correct option should address the primary diagnosis, not merely a downstream complaint."
    },
    {
      "id": "first_line_over_alternative",
      "text": "When multiple options are indicated for the primary diagnosis, prefer the standard first-line agent for that diagnosis in the described patient, unless the case provides a specific reason (allergy, intolerance, resistance, organ dysfunction, interaction) to choose an alternative. Do not default to a later-line or niche agent merely because a comorbidity is mentioned."
    }
  ],
  "focus_terms": [
    "primary diagnosis",
    "first-line therapy",
    "prior exposure",
    "retreatment",
    "contraindication",
    "drug interaction",
    "comorbidity",
    "secondary symptom",
    "indication match"
  ],
  "modules": {
    "patient_evidence": "Identify the stated primary diagnosis, the current and prior medicines, and any explicitly stated allergies, intolerances, or organ dysfunction. Separate facts that are stated from facts that are merely implied; do not treat an unstated interaction or contraindication as present.",
    "safety_check": "Check only for contraindications and interactions that are stated or strongly implied by the case. A named medication is not automatically disqualifying. Distinguish prior exposure from true contraindication, and verify compatibility with the patient's comorbidity and current regimen before rejecting an otherwise indicated option.",
    "option_selection": "Choose the option whose approved indication matches the primary diagnosis and that is standard first-line for the described patient. Eliminate options that treat only secondary symptoms, unrelated conditions, or wrong drug classes. Prefer first-line over later-line unless a specific stated reason justifies an alternative."
  }
}

{
  "diagnosis": "The agent over-weights the first plausible indication and under-uses patient-specific safety modifiers (organ impairment, interacting drugs, immunosuppression, constipation, prior therapy) when selecting among otherwise indicated options; it also treats absent facts as present and fails to distinguish first-line vs alternative therapy.",
  "skills": [
    {
      "id": "extract_patient_facts",
      "text": "Before choosing, explicitly list the stated diagnosis/indication, all current medicines, and every stated comorbidity or organ-function concern. Do not infer a fact that is not stated; if a safety-relevant fact is missing, treat it as unknown rather than present."
    },
    {
      "id": "indication_first",
      "text": "Filter options to those that treat the stated condition. Eliminate any option whose primary indication is unrelated to the diagnosis, even if it is otherwise familiar or safe."
    },
    {
      "id": "safety_modifier_check",
      "text": "For each remaining indicated option, check it against stated patient-specific modifiers: organ impairment (liver/kidney), immunosuppression, pregnancy, cardiac disease, constipation/bowel obstruction, and current drug interactions. Prefer the option with the fewest conflicts with stated facts."
    },
    {
      "id": "interaction_and_class_risk",
      "text": "When two options share an indication, compare their interaction and class-risk profiles against the patient's current medicines. Avoid combining agents with overlapping toxicity or a known interaction when a safer indicated alternative exists."
    },
    {
      "id": "first_line_vs_alternative",
      "text": "Distinguish first-line therapy from alternatives. Choose first-line when it is not contraindicated; choose an alternative only when a stated patient fact makes the first-line option unsafe or unavailable."
    },
    {
      "id": "avoid_absent_fact_invention",
      "text": "Do not assume allergy, renal failure, pregnancy, or other unstated conditions to justify an option. Base the choice only on facts present in the dialogue and the option's labeled indication."
    }
  ],
  "focus_terms": [
    "indication",
    "contraindication",
    "interaction",
    "organ impairment",
    "immunosuppression",
    "first-line",
    "alternative therapy",
    "stated fact"
  ],
  "modules": {
    "patient_evidence": "Extract only stated condition, current medicines, and relevant patient facts; mark missing safety facts as unknown.",
    "safety_check": "Check each indicated option against stated contraindications, organ impairment, immunosuppression, and drug interactions without inventing facts.",
    "option_selection": "Choose the indicated option with the best patient-specific safety profile, preferring first-line therapy unless a stated fact makes it unsafe."
  }
}

{
  "diagnosis": "The agent fails when it must select a medication for a stated active problem while accounting for an already-present medication whose class or mechanism overlaps with the options. Errors cluster into: (1) missing that an existing drug already occupies the therapeutic niche or contraindicates/allows a related agent, (2) confusing supportive-care or symptom-treatment options with definitive disease-modifying therapy, and (3) failing to recognize when a previously used biologic/immunosuppressant can be reused for the same indication rather than switching to an alternative brand or unrelated drug.",
  "skills": [
    {
      "id": "active_problem_targeting",
      "text": "Determine the currently active clinical problem that the medication choice is meant to address, not a secondary symptom or historical condition. Rank options by whether they are definitively indicated for that active problem; discard options that treat only a symptom, an unrelated condition, or a past problem."
    },
    {
      "id": "existing_therapy_overlap",
      "text": "Inventory all medicines the patient is already taking. If any current medicine already targets the active problem, do not reflexively add another agent in the same class or with the same mechanism unless the current medicine is described as inadequate, intolerable, or explicitly being replaced. Prefer the option that best matches the intended therapeutic role relative to existing therapy."
    },
    {
      "id": "mechanism_class_matching",
      "text": "For each option, identify its pharmacologic class and mechanism. Match that class to the active problem's established management pathway. When two options treat the same problem, choose based on patient-specific factors (pregnancy, blood pressure, renal/hepatic function, prior exposure) rather than brand familiarity or recency."
    },
    {
      "id": "prior_exposure_reuse",
      "text": "Consider documented prior exposure to a medication for the same or related condition. Previous use does not automatically mean the drug is contraindicated or unavailable; retreatment with the same agent may be appropriate unless the history states treatment failure, intolerance, or an absolute contraindication. Do not substitute a different brand of the same molecule or an unrelated drug without a stated reason."
    },
    {
      "id": "pregnancy_safety_filter",
      "text": "When pregnancy is stated, filter options for pregnancy contraindications or warnings. Eliminate agents known to be unsafe or not indicated in pregnancy before considering efficacy. This filter applies even when the suspected diagnosis is uncertain; safety constraints remain fixed."
    },
    {
      "id": "no_invented_facts",
      "text": "Treat only explicitly stated patient facts as present. Do not infer a missing diagnosis, pregnancy status, medication, or contraindication. If an option requires a fact that is absent, do not assume it; instead, choose the option whose indication and safety can be supported by the stated evidence alone."
    }
  ],
  "focus_terms": [
    "active problem",
    "currently taking",
    "already on",
    "contraindication in pregnancy",
    "prior exposure",
    "retreatment",
    "same class",
    "supportive care",
    "definitive therapy",
    "not stated"
  ],
  "modules": {
    "patient_evidence": "Extract the active problem, all current medicines with doses/duration if given, pregnancy status, relevant organ function, blood pressure, and any prior medication exposures. Keep stated facts separate from clinician speculation; do not convert a suspected diagnosis into a confirmed one.",
    "safety_check": "Check each option against stated patient-specific contraindications, pregnancy, current medicines, and prior exposures. Distinguish prior exposure from prior failure or intolerance. Do not invent missing facts to justify or eliminate an option.",
    "option_selection": "Choose the option that is definitively indicated for the active problem and compatible with current therapy and patient-specific safety. Rank by indication match first, then safety, then appropriateness relative to drugs the patient is already taking. Do not select an option solely because it is less familiar or newer."
  }
}

{
  "diagnosis": "The agent over-weights the first plausible indication and under-weights patient-specific safety modifiers (current medicines, comorbidity, and route/formulation fit), so it sometimes picks a drug that is indicated in general but less appropriate for this patient than an alternative. Failures cluster into: (1) ignoring additive CNS depression from current opioids when choosing a sedative; (2) choosing a systemic or intra-articular formulation without checking whether the clinical setting matches the route; (3) treating a comorbidity as a contraindication when it is not, and conversely missing that a comorbidity should steer selection; (4) failing to prefer a drug that treats the active disease process over one that only relieves symptoms; (5) failing to distinguish first-line/standard-of-care from merely plausible options.",
  "skills": [
    {
      "id": "extract_patient_facts",
      "text": "Before selecting, explicitly list: the stated diagnosis/indication, every current medicine with its drug class, relevant comorbidities, and any stated prior therapy or treatment response. Do not infer a fact that is not stated; if a fact is absent, treat it as unknown rather than present."
    },
    {
      "id": "screen_current_med_interactions",
      "text": "For each candidate, check interaction and additive-effect risk against every current medicine. If the patient is already on a CNS depressant (e.g., opioid), avoid adding another CNS depressant unless it is clearly the best-supported option and the risk is acknowledged; prefer a non-additive alternative when one exists."
    },
    {
      "id": "match_route_and_setting",
      "text": "Match the drug's route and formulation to the clinical setting. Prefer systemic therapy for systemic or acute conditions; reserve intra-articular or procedure-only agents for the specific local/procedural context. Do not select a long-acting injectable or procedural sedative for routine outpatient use when an oral/systemic equivalent is appropriate."
    },
    {
      "id": "comorbidity_steering",
      "text": "Use comorbidities to steer selection, not to automatically exclude. A comorbidity is a contraindication only if the drug label or mechanism makes it one; otherwise, prefer the option that is safest and most appropriate given that comorbidity. Do not invent a contraindication from a comorbidity alone."
    },
    {
      "id": "treat_active_disease_over_symptom",
      "text": "When the active disease process is not controlled on current therapy, prefer a drug that treats the underlying process (disease-modifying or definitive therapy) over one that only provides symptomatic or adjunctive relief, provided safety and interactions are acceptable."
    },
    {
      "id": "rank_by_standard_of_care",
      "text": "Among options that are all indicated, rank by standard-of-care and fit: first-line/definitive therapy for the stated condition and patient > plausible but non-standard > unrelated. Choose the highest-ranked option that also passes the interaction, route, and comorbidity checks."
    }
  ],
  "focus_terms": [
    "current medicines",
    "drug class",
    "additive CNS depression",
    "route of administration",
    "intra-articular",
    "systemic therapy",
    "comorbidity",
    "contraindication",
    "active disease process",
    "symptomatic relief",
    "first-line therapy",
    "standard of care"
  ],
